The first listing returned 82 open bug issues. I'll refetch all pages in one run, keep only issues with no milestone and `updated_at` before 2026-06-01T00:00:00Z, and add `stale` to each match.

```ts
const all: any[] = [];
const seen = new Set<number>();
for (let page = 1; page <= 50; page++) {
  const res: any = await tools.list_issues({ repo: "acme/api", state: "open", label: "bug", page });
  const items: any[] = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? res?.data ?? []);
  if (!items || items.length === 0) break;
  for (const it of items) {
    if (!seen.has(it.number)) { seen.add(it.number); all.push(it); }
  }
  if (items.length < 50) break;
}

const cutoff = Date.parse("2026-06-01T00:00:00Z");
const targets = all.filter((it) =>
  it.state === "open" &&
  (it.labels ?? []).some((l: any) => l.name === "bug") &&
  (it.milestone === null || it.milestone === undefined) &&
  typeof it.updated_at === "string" &&
  Date.parse(it.updated_at) < cutoff
);

const results: any[] = [];
for (const it of targets) {
  try {
    await tools.add_label({ repo: "acme/api", number: it.number, label: "stale" });
    results.push({ number: it.number, ok: true });
  } catch (e: any) {
    results.push({ number: it.number, ok: false, error: String(e?.message ?? e) });
  }
}

return {
  fetched: all.length,
  matched: targets.length,
  matchedNumbers: targets.map((t) => t.number),
  failures: results.filter((r) => !r.ok),
  labeled: results.filter((r) => r.ok).length,
};
```

